    "title": "LG新能源波兰工厂受益于电动车与储能需求，即将实现盈利",
    "link": "https://36kr.com/newsflashes/4034881617450118?f=rss",
    "pub_date": "2026-10-21 08:48:10",
    "author": "",
    "description": "据韩国经济日报援引未具名业界消息报道，受欧洲电动汽车需求走强以及部分生产线转向储能系统（ESS）的提振，LG新能源位于波兰的工厂产能利用率得以提升，该工厂有望在第四季度实现营业利润扭亏为盈。报道指出，该弗罗茨瓦夫工厂第三季度的产能利用率已升至60%至65%区间，创下自2024年第三季度以来的最高水平。通常情况下，当该工厂的产能利用率达到60%-70%初段区间时，即可实现盈亏平衡。（新浪财经）",
