    "description": "2026年10月21日 一个民族的历史，往往由一些跨越时代的关键时刻所书写，并成为后来者理解现实、思考未来的重要思想来源。中国共产党领导的长征正是这样一段历史。长征实现了中国共产党和中国革命事业的重大转折，体现了在极端困难条件下保持战略定力，同时根据现实变化不断调整方法和路径的应变能力。90年后的今天，长征所蕴含的战略智慧，对于应对当下充满不确定性的国际环境具有重要启示意义。 长征发生在中国革命处于严重困难的时期。中国共产党人没有因一时…",
    "content": "2026年10月21日 一个民族的历史，往往由一些跨越时代的关键时刻所书写，并成为后来者理解现实、思考未来的重要思想来源。中国共产党领导的长征正是这样一段历史。长征实现了中国共产党和中国革命事业的重大转折，体现了在极端困难条件下保持战略定力，同时根据现实变化不断调整方法和路径的应变能力。90年后的今天，长征所蕴含的战略智慧，对于应对当下充满不确定性的国际环境具有重要启示意义。 长征发生在中国革命处于严重困难的时期。中国共产党人没有因一时挫折而动摇根本目标，而是把保存和发展革命力量、继续推进革命事业作为首要战略任务。…"
