    "content": "2026年10月21日 新华社索非亚10月19日电&nbsp;&nbsp;（记者林浩、姚雨璘）中共中央政治局委员、外交部长王毅19日在索非亚同保加利亚外长佩特罗娃共同会见记者时表示，此次出访作为习近平主席特别代表出席了亚信峰会，还访问了阿塞拜疆、克罗地亚、黑山和保加利亚。他借此机会分享了此次欧亚之行的四点感受。 第一，信任是和平基石。中方向各方传递的明确信息是：坚定信心、锲而不舍、对话协商、互谅互让、重建信任、共筑和平。中方将始终站在历史正确一边，为消弭信任赤字、化解危机冲突履行大国担当，发挥应有作用。 第二，友谊…"
