    "content": "2026年10月21日 伟大征程，不朽丰碑。 1934年10月到1936年10月，两轮寒暑，红军纵横十余省，长驱二万五千里，铸就光耀千秋的伟大长征精神。 习近平总书记深刻指出：“这一惊天动地的革命壮举，是中国共产党和红军谱写的壮丽史诗，是中华民族伟大复兴历史进程中的巍峨丰碑。”“弘扬伟大长征精神，走好今天的长征路，是新的时代条件下我们面临的一个重大课题。” 知之愈明，行之愈笃。从于都到湘江，从遵义到将台堡，习近平总书记一次次到长征途经之地考察，一次次深情重温长征故事，一次次发表重要讲话，引领全党全社会从光辉历史中汲…"
