    "content": "2026年10月21日 扎根生活书写奋斗，以文润心凝聚共识，葆有爱国情怀，凝聚民族之魂，在改革创新中激扬奋进力量 精神的力量，穿越时空、激荡人心。 曾经，红军长征从出发地到落脚点耗时两年之久，何其壮烈。如今，江西瑞金至陕西延安直达高铁G3998次复兴号列车开行，实现“当日达”。 百年前，“奥运三问”振聋发聩、饱含辛酸。今天，体育强国建设步履坚实，第二十届亚运会赛场上，中国体育代表团创亚运会境外参赛最好成绩。 从一项项大国工程、一个个拼搏身影中，可以读出勤劳勇敢、自强不息的民族品格。绵延千年的精神传统，于时代前行中不…"
