    "content": "2026年10月21日 本报北京10月20日电&nbsp;&nbsp;10月20日，新华社发表题为《长征，永远在路上——献给中国工农红军长征胜利90周年》的政论文章。全文如下： （一） 历史长河奔腾不息，无数行迹湮没于岁月洪流。九十载风雨淘洗，中国工农红军长征这条地球上的“红飘带”鲜亮如初，在我们心底激荡起深厚绵长的精神回响。 1936年深秋，朔风漫过黄土高原。历经长途艰难跋涉，红一、红四方面军会师会宁，红一、红二方面军会师将台堡，实现三大主力红军会师。漫漫征途，红军将士以信念为炬、以血肉为盾，击退上百万穷凶极恶的…"
