    "content": "2026年10月21日 在中国人民革命军事博物馆举办的“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”自9月25日面向公众开放以来，累计接待观众50余万人次。近期，全国各地长征主题展览迎来参观热潮。本报记者走进多地博物馆、纪念馆，从一艘木船、一杆铁秤、三扇门板、一只木桶中，读懂红军颠扑不破的信仰，感受一针一线背后的鱼水深情。 一艘木船见证军民同心 在江西于都中央红军长征出发纪念馆，一艘木船静静陈列，船体斑驳沧桑——于都县老船工李声仁曾用这艘船摆渡红军渡过于都河。 1934年10月，中央红军主力8.6万余人…"
