    "content": "2026年10月21日 10月12日至18日，国际货币基金组织（IMF）与世界银行集团2026年秋季年会在泰国曼谷举行，来自191个国家和地区的近2万名参会人员围绕如何增强世界经济韧性、合作应对经济挑战展开讨论。其间，IMF发布的最新一期《世界经济展望报告》预计，2026年全球经济增长3.1%，低于2025年的3.5%，2027年增速有望回升至3.4%；全球通胀率预计从2026年的4.7%回落至2027年的4.1%。 报告认为，当前全球经济增长受到两重因素的共同影响。一方面，中东地区冲突引发能源及其他大宗商品价格上…"
