    "content": "2026年10月21日 永不褪色的“映山红” 本报记者&nbsp;&nbsp;程&nbsp;&nbsp;焕 贵州省遵义市桐梓县 映山红，遵义市花，映照红色基因在这座“转折之城”薪火相传 在贵州省遵义市桐梓县娄山关街道杉坪村，每到映山红盛开的时节，层层叠叠的红色把山岗染得灼灼生辉。鲜艳的映山红年年绽放，见证着当年的卓绝，也映照着今日之繁华。 “当年红军长征时，两次从我们村经过，就是沿着这条路攻下娄山关的。”村民罗运发指向南侧山脊，一条老旧的石板路映入眼帘。沿路前行，便是素有“黔北第一险隘”之称的娄山关。 1935年初…"
