    "description": "2026年10月21日 江西于都：兰花小镇产业兴 1934年10月，江西于都河畔，8.6万余名红军战士集结渡河，踏出万里长征的第一步。90多年后，地处于都禾丰镇的兰花小镇，已是国内最大的兰花生产基地之一，红色记忆与田园风光交相辉映。 1700余个兰花品种，年产兰花3800万盆，全镇5000余户农户参与兰花产业，年产值超3亿元，远销日韩等国际市场。朵朵兰花，是老区人民传承红色基因、奔赴幸福未来的生动写照。 湖南汝城：金银花开致富路 193…",
    "content": "2026年10月21日 江西于都：兰花小镇产业兴 1934年10月，江西于都河畔，8.6万余名红军战士集结渡河，踏出万里长征的第一步。90多年后，地处于都禾丰镇的兰花小镇，已是国内最大的兰花生产基地之一，红色记忆与田园风光交相辉映。 1700余个兰花品种，年产兰花3800万盆，全镇5000余户农户参与兰花产业，年产值超3亿元，远销日韩等国际市场。朵朵兰花，是老区人民传承红色基因、奔赴幸福未来的生动写照。 湖南汝城：金银花开致富路 1934年，红军长征突破第二道封锁线后，进入湖南汝城县文明司（今文明瑶族乡）休整，当地…"
