    "content": "2026年10月21日 以伟大建党精神为源头的中国共产党人精神谱系，是由不同地域、不同历史阶段形成的党的伟大精神构成的有机整体。土地革命战争时期，照金苏区作为西北第一个山区革命根据地，孕育了照金精神；中国工农红军在战略转移的漫漫征途中历经生死考验，铸就了彪炳史册的长征精神；红军长征到达陕北之后，党中央以延安为总后方探索局部执政，淬炼形成了延安精神。由陕甘边革命根据地与陕北革命根据地发展形成的陕甘革命根据地，作为土地革命战争后期全国硕果仅存的完整革命根据地、党中央和各路长征红军的落脚点和八路军主力奔赴抗日前线的出发点…"
