    "description": "2026年10月21日 人民币国际化是推进高水平对外开放的重要内容。习近平总书记在党的二十大报告中指出：“有序推进人民币国际化。”“十五五”规划纲要提出：“推进人民币国际化，拓展人民币在国际贸易和投融资中的使用”。推进人民币国际化，既是中国需要，也是全球需要。 当前，全球地缘政治风险持续上升，世界经济正在发生深刻的结构性变化，全球南方国家在世界经济、贸易、资本流动中的份额和影响力不断提升。中国国际发展知识中心发布的《全球发展报告2025…",
    "content": "2026年10月21日 人民币国际化是推进高水平对外开放的重要内容。习近平总书记在党的二十大报告中指出：“有序推进人民币国际化。”“十五五”规划纲要提出：“推进人民币国际化，拓展人民币在国际贸易和投融资中的使用”。推进人民币国际化，既是中国需要，也是全球需要。 当前，全球地缘政治风险持续上升，世界经济正在发生深刻的结构性变化，全球南方国家在世界经济、贸易、资本流动中的份额和影响力不断提升。中国国际发展知识中心发布的《全球发展报告2025》指出，全球南方国家在世界经济中的份额从上世纪80年代的约25%升至2024年的…"
