    "description": "2026年10月21日 2016年2月，寒冷中孕育着浓浓春意，习近平总书记沿着崎岖山路来到江西省井冈山市茅坪镇神山村，察支部建设，进农家院落，看产业规划，问民生冷暖。总书记对乡亲们说，我们党是全心全意为人民服务的党，将继续大力支持老区发展，让乡亲们日子越过越好。在扶贫的路上，不能落下一个贫困家庭，丢下一个贫困群众。 革命老区破茧成蝶的星火自井冈山燃起，燎原神州。 十年砥砺，沧桑巨变。从“空心村”到“活力村”，从“贫困样本”到“振兴名片”…",
    "content": "2026年10月21日 2016年2月2日，习近平总书记走访红军烈士后代左秀发家，并在他家门口与村民一起打糍粑。如今，左秀发老人已过世，但他的家人经营特色农副产品，生意红红火火。儿子左香云（中）当选了全国人大代表。左香云和母亲彭冬莲（右二）在教来村里参观学习的大学生们打糍粑。 \"> 神山村种植的茶树开满茶花。 \"> 2016年2月2日，习近平总书记和村民李宗吾一起打糍粑。现在，70多岁的李宗吾精力充沛，白天经营民宿，傍晚侍弄自家菜园子。 \"> 2016年2月2日，习近平总书记走进贫困户张成德（左）、彭夏英家中，同他…"
