    "content": "2026年10月21日 本报北京10月20日电&nbsp;&nbsp;（记者谷业凯）国家知识产权局、海关总署日前印发《关于强化知识产权协同保护的意见》。意见提出，在保障数据安全的基础上，建立数据共享应用合作长效工作机制。国家知识产权局定期向海关总署提供商标、专利等基础数据信息，便利知识产权权利人办理海关备案；共享驰名商标确认信息、撤销或者宣告无效的商标信息以及重大专利侵权纠纷行政裁决决定信息，辅助海关执法。 强化调查协助方面，意见明确，知识产权管理部门处理涉及进出口货物的商标、专利侵权案件请求海关协助的，海关应当予…"
