    "description": "2026年10月21日 本报兰州10月20日电 （记者宋朝军）甘肃省林草局等七部门近日联合印发《甘肃省关于加快建设现代化国有林场的实施意见》。 实施意见对未来5至10年甘肃省现代化国有林场建设作出系统部署，明确了分阶段建设目标：到2030年，全省国有林场管理体制进一步完善，森林资源稳定增长，单位面积森林蓄积量提高4.75%，特色产业体系基本形成，智慧林场体系基本建立；到2035年，全省国有林场生态质量全面改善，绿色产业体系更加健全，管理…",
