    "content": "2026年10月21日 当前正处求职招聘旺季，一些不法分子冒用央国企名义发布虚假招聘信息引流，打着“内部推荐”“直签保录”等幌子，甚至伪造招聘录用材料，诱导求职者支付高额费用，严重侵害求职者合法权益，扰乱人力资源市场秩序。 人力资源社会保障部、中央网信办、教育部、公安部、国务院国资委等发布风险提示，提醒广大求职者提高风险防范意识，谨防上当受骗。 利用话术引流，贩卖求职焦虑 有关部门提示，不法分子实施诈骗往往首先冒用央国企名义编造虚假招聘信息进行引流，通过社交、直播、短视频平台或线上社群、网络论坛、交流社区等，以“央…"
