    "description": "2026年10月21日 2026年6月，《国家人权行动计划（2026—2030年）》发布，这是中国政府制定和实施的第五期国家人权行动计划。中国实践吸引着世界目光。在联合国人权理事会第六十三届会议期间，多位中外专家齐聚日内瓦，聚焦中国第五期国家人权行动计划，深入探讨国家人权行动计划的中国经验及其对全球人权治理的启示意义。5期国家人权行动计划的接续制定和实施，集中体现了中国人权事业发展的连续性与稳定性，为世界观察和理解中国如何将人权保障承诺…",
    "content": "2026年10月21日 2026年6月，《国家人权行动计划（2026—2030年）》发布，这是中国政府制定和实施的第五期国家人权行动计划。中国实践吸引着世界目光。在联合国人权理事会第六十三届会议期间，多位中外专家齐聚日内瓦，聚焦中国第五期国家人权行动计划，深入探讨国家人权行动计划的中国经验及其对全球人权治理的启示意义。5期国家人权行动计划的接续制定和实施，集中体现了中国人权事业发展的连续性与稳定性，为世界观察和理解中国如何将人权保障承诺转化为人权治理实践，进而转化为人权治理效能，提供了一个独特而可靠的窗口。 国家人…"
