    "description": "2026年10月21日 今年三季度国民经济运行“成绩单”中，两组数据尤为亮眼。 一组来自增长动能，以高端制造、数智经济、现代服务等为代表的新动能对前三季度经济增长的贡献率继续保持在40%以上。一组来自外贸出口，前三季度，货物进出口总额同比增长18.8%，其中装备制造业引领作用突出，贡献了近九成的出口增量。 新质生产力持续拔节生长，装备制造业“压舱石”作用凸显。把两组数据放在一起看，二者各有侧重，又相互印证，共同勾勒出中国经济向新向优的清…",
    "content": "2026年10月21日 今年三季度国民经济运行“成绩单”中，两组数据尤为亮眼。 一组来自增长动能，以高端制造、数智经济、现代服务等为代表的新动能对前三季度经济增长的贡献率继续保持在40%以上。一组来自外贸出口，前三季度，货物进出口总额同比增长18.8%，其中装备制造业引领作用突出，贡献了近九成的出口增量。 新质生产力持续拔节生长，装备制造业“压舱石”作用凸显。把两组数据放在一起看，二者各有侧重，又相互印证，共同勾勒出中国经济向新向优的清晰态势。 新，体现在增长动能的转换中。工业垂类大模型走进钢厂、港口，把工艺经验转…"
