    "content": "2026年10月21日 1934年10月，中央红军主力等8.6万余人星夜渡过于都河，踏上万里远征。 于都中央红军长征集结出发历史博物馆里，一台斑驳褪色的手摇缝纫机静静陈列，当年于都红军战士葛接调挑着它随军出征，见证了苏区群众一针一线支援红军的赤诚。 一根纱线，牵起历史与当下。 从简单工装到国风旗袍，从人工缝制到智慧车间，从代工贴牌到品牌出海……近年来，于都着力发展纺织服装产业，聚集相关企业3850余家，带动约30万人就业，全行业营收超千亿元，获评中国品牌服装制造名城、全国时尚服装特色产业集聚区、全国纺织服装产业十大…"
