    "content": "新华社奥斯陆10月20日电（记者张玉亮）挪威首相斯特勒、芬兰总统斯图布和乌克兰总统泽连斯基20日在挪威首都奥斯陆与美方特使举行乌克兰问题会谈。与会的美总统特使威特科夫定于21日前往俄罗斯圣彼得堡，与俄总统普京会面并通报此次会谈要点。 据挪威广播公司报道，此次会谈应乌方请求举行，旨在进一步梳理可向俄方提出的和平方案要点。英国、法国、德国、波兰以及欧盟、北约代表以视频方式参加了扩大会议。 斯特勒在会后与泽连斯基、斯图布共同举行的记者会上说，会谈富有建设性，讨论涉及乌克兰安全、战后重建、领土、制裁及欧洲安全秩序等问题。 …"
