    "title": "上海3元爱心餐背后：一个00后妈妈和聚起来的一群人",
    "link": "https://m.thepaper.cn/newsDetail_forward_34283042",
    "pub_date": "2026-10-21 07:58:58",
    "author": "",
    "description": "3块钱，在上海能买什么？不够一杯奶茶，但可以是一份爱心餐。最近，在上海儿童医学中心张江院区门口，一个00后宝妈每天会支起一个小摊，向患者的家属售卖自己做的三元套餐。从最初一个人操持，到后面一群人忙活，患者家属来搭把手，陌生人放下物资就走，还有驱车赶来帮忙的志愿者......这个小摊，成了城市里善意循环的“桥”。",
    "content": "3块钱，在上海能买什么？不够一杯奶茶，但可以是一份爱心餐。最近，在上海儿童医学中心张江院区门口，一个00后宝妈每天会支起一个小摊，向患者的家属售卖自己做的三元套餐。从最初一个人操持，到后面一群人忙活，患者家属来搭把手，陌生人放下物资就走，还有驱车赶来帮忙的志愿者......这个小摊，成了城市里善意循环的“桥”。"
