    "content": "本文为 澎湃号·湃客科技 × 节点美妆 联合出品，湃客科技栏目独家首发，未经允许禁止转发 文&nbsp; | 杨蕾 又到一年的双11，香水香氛赛道蓄势爆发，但这一轮消费热潮，不只是比拼香调和大牌折扣。 市场正在发生微妙的转变：香气正在成为年轻人的情绪载体，甚至衍生出香水玄学的消费风潮。 过去一年，年轻人选购香水的方式变了。不再靠了解前中后调，而是查“五行”和“星座”。在社交媒体上搜香水，种草博主不会再向网友描述某一瓶香水的香味是怎样的，取而代之的是： “香气，是你低谷期的解药。” “每个人都自带独属于自己的内在磁场…"
