    "description": "10月20日，阿联酋联邦最高委员会成员、拉斯海玛酋长国酋长谢赫·萨乌德·本·萨克尔·卡西米率团到访小鹏汇天飞行汽车量产工厂，参观全球首条飞行汽车量产线，并为首架投入阿联酋先进低空飞行监管示范区的陆地航母飞行器（X3-F）下线揭幕，现场接收该架试验用机。 记者了解到，与以往在展会、演示现场的静态观摩不同，酋长接过的是一台刚下产线、具备完整量产工艺、可直接投入试运行的飞行器。首批试验用机交付阿联酋后，将在阿联酋民航局监管下开展沙盒试运行。下…",
    "content": "10月20日，阿联酋联邦最高委员会成员、拉斯海玛酋长国酋长谢赫·萨乌德·本·萨克尔·卡西米率团到访小鹏汇天飞行汽车量产工厂，参观全球首条飞行汽车量产线，并为首架投入阿联酋先进低空飞行监管示范区的陆地航母飞行器（X3-F）下线揭幕，现场接收该架试验用机。 记者了解到，与以往在展会、演示现场的静态观摩不同，酋长接过的是一台刚下产线、具备完整量产工艺、可直接投入试运行的飞行器。首批试验用机交付阿联酋后，将在阿联酋民航局监管下开展沙盒试运行。下一阶段，双方将围绕产品认证、跨酋长国航线规划与运营体系搭建推进具体工作，为个人低…"
