    "content": "2026年11月，《联合国气候变化框架公约》第三十一次缔约方大会（COP31）将在土耳其安塔利亚召开，“动态与韧性健康系统”被列为行动议程的优先主题之一，大会首日即设“健康日”。 从COP28首设健康日到COP30发布《贝伦卫生行动计划》，健康议题在全球气候治理中的权重持续攀升。 《柳叶刀倒计时》2025年全球报告指出，在监测气候相关健康威胁的20项关键指标中，有12项已达到有记录以来的最高水平。自20世纪90年代以来，热相关死亡率上升23%，年均热相关死亡人数达54.6万人；2020至2024年间，平均84%的热…"
