    "description": "新华社巴黎10月20日电（记者罗毓）第八届“巴黎协定之友”高级别对话19日至20日在法国巴黎举行，来自20多个国家的高级别代表围绕多边主义、绿色转型、气候融资等议题展开深入坦诚交流。会议由前中国气候变化事务特使解振华与前法国气候变化谈判大使、欧洲气候基金会首席执行官劳伦斯·图比亚娜共同主持。 开幕致辞上，解振华回顾了《巴黎协定》达成以来全球气候治理和绿色低碳转型取得的积极进展，强调要坚持多边主义和公平原则、促进良性竞争与务实合作，以及统…",
    "content": "新华社巴黎10月20日电（记者罗毓）第八届“巴黎协定之友”高级别对话19日至20日在法国巴黎举行，来自20多个国家的高级别代表围绕多边主义、绿色转型、气候融资等议题展开深入坦诚交流。会议由前中国气候变化事务特使解振华与前法国气候变化谈判大使、欧洲气候基金会首席执行官劳伦斯·图比亚娜共同主持。 开幕致辞上，解振华回顾了《巴黎协定》达成以来全球气候治理和绿色低碳转型取得的积极进展，强调要坚持多边主义和公平原则、促进良性竞争与务实合作，以及统筹发展与民生、保持坦诚对话的重要性。他指出，尽管面临多重挑战，中国应对气候变化的…"
