    "content": "作为职业的计算 1791年，法国革命政府推行十进制度量衡，角度也要改用十进制，直角从九十度改为一百度。原有的对数表因此不再适用，必须按新的角度重新计算。这类表格是天文、航海和工程测量的日常工具，一处誊写或计算错误就可能沿着整张表传下去。主持工程的法国数学家加斯帕尔·德·普罗尼（Gaspard de Prony）要算出约二十万个对数，单靠少数专家伏案苦算，无论如何也算不完。他在亚当·斯密的《国富论》里读到制针工场的分工，决定“像制造别针那样制造我的对数”。一张表从此不再由一个人从头算到尾，计算被拆成一道道工序，分给不…"
