    "content": "新华社突尼斯10月20日电（记者周昊瑾）的黎波里消息：利比亚国民代表大会20日在社交媒体宣布，该机构当天经投票表决，废除其此前“与土耳其断绝政治关系的决议”。 利国民代表大会同时表示，该机构当天还投票批准了2019年利比亚民族团结政府与土耳其签署的有关地中海“海事管辖权”的谅解备忘录。 2011年卡扎菲政权被推翻后，利比亚陷入动荡。目前，得到联合国承认的利民族统一政府与支持它的武装力量控制利比亚西部部分地区，利国民代表大会与“国民军”结盟，控制东部和南部大部分地区，双方割据对峙。 2019年11月，土耳其与利民族团…"
