    "content": "新华社洛杉矶10月20日电（记者高山）美国司法部堪萨斯州联邦检察官办公室说，一名威胁要在该州19日举行的共和党集会上刺杀美国总统特朗普的男子已经被捕。 综合上述办公室通报以及当地媒体报道，24岁的堪萨斯州男子杰登·里德在社交媒体上一篇当地电视台新闻报道下发表的评论，引起执法部门关注。 里德写道：“说真的，我们干脆开枪打特朗普吧，我们的枪手在哪儿？我受够了这种为钱而活的日子。”他在评论中自称搞到了枪和子弹。 在另一篇新闻报道下的独立评论中，里德据称写道：“能不能就在堪萨斯州把他干掉？我自己来都行。”一分钟后，里德又发…"
