    "content": "新华社阿布贾10月20日电（记者洪泽华）尼日利亚政府20日说，该国首都阿布贾发现近期首例埃博拉确诊病例。 尼日利亚卫生和社会福利部发布公告说，经实验室检测，一名从乌干达乘机抵达阿布贾的女子确诊感染埃博拉病毒，目前已接受隔离治疗。同时，尼日利亚政府已启动防止病毒传播的公共卫生措施。 尼日利亚人口超过2亿，是非洲人口最多的国家。2014年7月至10月，该国曾暴发埃博拉疫情。 刚果（金）5月15日宣布暴发埃博拉疫情。本轮疫情由本迪布焦型埃博拉病毒引发，目前尚无针对该型病毒的获批疫苗或特异性疗法。世界卫生组织8月表示，刚果…"
