    "description": "新华社雅加达10月20日电（记者李嘉聪）印度尼西亚万丹省搜救部门20日晚通报，当天下午在爪哇岛西端附近海域发生的客轮火灾事故中，船上460人已全部安全撤离。 当地搜救部门说，起火客轮名为“巴图曼迪”号，载有420名乘客和40名船员。当地时间20日16时15分左右，客轮在驶入万丹省默拉克港的航道时突然起火。 事故发生后，当地搜救部门派遣救援人员和船只赶赴现场，展开人员疏散和灭火工作。截至18时30分，船上所有乘客和船员均已安全撤离，并被转…",
    "content": "新华社雅加达10月20日电（记者李嘉聪）印度尼西亚万丹省搜救部门20日晚通报，当天下午在爪哇岛西端附近海域发生的客轮火灾事故中，船上460人已全部安全撤离。 当地搜救部门说，起火客轮名为“巴图曼迪”号，载有420名乘客和40名船员。当地时间20日16时15分左右，客轮在驶入万丹省默拉克港的航道时突然起火。 事故发生后，当地搜救部门派遣救援人员和船只赶赴现场，展开人员疏散和灭火工作。截至18时30分，船上所有乘客和船员均已安全撤离，并被转移至附近其他客轮及默拉克港码头。部分伤者被送往医院接受治疗。 搜救部门说，此次救…"
